private void replaceRuleIdsByRuleKeys(@Nullable Facets facets, List<RuleDefinitionDto> alreadyLoadedRules){
  if (facets == null || facets.get(PARAM_RULES) == null) {
    return;
  }
  Object rawRulesFacet = facets.get(PARAM_RULES);
  if (!(rawRulesFacet instanceof LinkedHashMap)) {
    LOGGER.error("Unexpected type for rules facet: {}", rawRulesFacet != null ? rawRulesFacet.getClass().getName() : "null");
    return;
  }
  LinkedHashMap<String,Long> rulesFacet = (LinkedHashMap<String,Long>) rawRulesFacet;
  try (DbSession dbSession = dbClient.openSession(false)){
    Set<String> ruleKeysToLoad = new HashSet<>(rulesFacet.keySet());
    ruleKeysToLoad.removeAll(alreadyLoadedRules.stream().map(r -> r.getKey().toString()).collect(Collectors.toList()));
    // Filter out keys that are not valid integers to avoid NumberFormatException
    Set<String> validIntegerKeys = ruleKeysToLoad.stream().filter(s -> s.matches("\\d+")).collect(Collectors.toSet());
    Map<Integer,RuleKey> idToRuleKey = Stream.concat(
      alreadyLoadedRules.stream(),
      dbClient.ruleDao().selectDefinitionByIds(dbSession, Collections2.transform(validIntegerKeys, Integer::parseInt)).stream()
    ).collect(Collectors.toMap(RuleDefinitionDto::getId, RuleDefinitionDto::getKey));
    LinkedHashMap<String,Long> newRulesFacet = new LinkedHashMap<>();
    rulesFacet.forEach((k, v) -> {
      try {
        Integer id = Integer.parseInt(k);
        RuleKey ruleKey = idToRuleKey.get(id);
        if (ruleKey != null) {
          newRulesFacet.put(ruleKey.toString(), v);
        } else {
          LOGGER.error("Rule with id {} is not available in database", k);
        }
      } catch (NumberFormatException e) {
        LOGGER.error("Invalid rule id format: {}", k);
      }
    });
    rulesFacet.clear();
    rulesFacet.putAll(newRulesFacet);
  }
}
